from __future__ import annotations

__doc__ = """
Backend abstraction combining builder, build chain, library, wrappers, and
resource presets.

The goal of this module is to hide backend-specific assembly details behind one
high-level object per language/backend target. A backend instance owns:

- the default builder class,
- the default build-chain composition,
- the library and wrapper classes,
- convenient resource presets,
- and user-facing helpers for ADAA assignment generation.
"""

