_BACKEND_REGISTRY_LOADED = False

def _default_keymap_for(variable) -> Any:
    if isinstance(variable, type) and issubclass(variable, InstructionVariable):
        config = getattr(variable, "_default_config", None)
        if config is not None:
            return config
        instance = variable()
        return instance.input_config or instance.output_config
    if isinstance(variable, InstructionVariable):
        return variable.input_config or variable.output_config
    return None


def _resolve_omp_num_threads(backend: "Backend") -> int:
    backend_value = backend.configuration.get_nested(
        "omp",
        "num_cores",
        default=None,
    )
    if backend_value is None:
        backend_value = backend.general_configuration.get_nested(
            "runtime",
            "num_processors",
            default=1,
        )
    return max(1, int(backend_value))


def _clone_c_omp_resource(*, num_threads):
    from .c.c_builder import CComputeResource
    from .c.c_resource import OMPCSingleLayerResource

    root = OMPCSingleLayerResource(
        descriptor="omp c root",
        num_threads=num_threads,
    )
    root.append_resource_layer(CComputeResource("omp c fallback"))
    return root


def _clone_fortran_omp_resource(*, num_threads):
    from .fortran.fortran_builder import FortranComputeResource
    from .fortran.fortran_resource import OMPFortranSingleLayerResource

    root = OMPFortranSingleLayerResource(
        descriptor="omp fortran root",
        num_threads=num_threads,
    )
    root.append_resource_layer(FortranComputeResource("omp fortran fallback"))
    return root


@dataclass(frozen=True)
class AssignmentConfig:
    """User-facing configuration for backend ADAA assignment generation."""

    status: str = "RW"
    family: str | None = None
    factory: Any = None
    adaa_class: type[GenericADAA] | None = None
    layout: Any = None
    components: tuple[str, ...] | None = None
    selected_keys: tuple[str, ...] | None = None
    dtype: str | None = None
    size: int | None = None
    is_buffer: bool = False
    options: dict[str, Any] | None = None
    # compatibility fallback for the old semantic split
    real: bool | None = None
    imag: bool | None = None


Config = AssignmentConfig


class Backend:
    """High-level backend object combining build-chain and runtime choices."""

    IDENTIFIER: ClassVar[str] = "generic"
    VERSION: ClassVar[str] = "v1"
    KEYWORDS: ClassVar[tuple[str, ...]] = ("generic",)

    BUILDER_CLASS: ClassVar[type[Builder] | None] = None
    LIBRARY_CLASS: ClassVar[type | None] = None
    WRAPPER_LIBRARY_CLASS: ClassVar[type | None] = None
    BUILDCHAIN_CLASS: ClassVar[type[BuildChain]] = BuildChain

    REAL_ADAA_CLASS: ClassVar[type[GenericADAA] | None] = None
    IMAG_ADAA_CLASS: ClassVar[type[GenericADAA] | None] = None
    COMPLEX_ADAA_CLASS: ClassVar[type[GenericADAA] | None] = None
    ADAA_FAMILIES: ClassVar[dict[str, Any]] = {}

    DEFAULT_VALIDATORS: ClassVar[tuple[type, ...]] = (
        SingleMapApplyChainValidator,
    )
    DEFAULT_OPTIMIZERS: ClassVar[tuple[type, ...]] = ()

    _REGISTRY: ClassVar[dict[str, type["Backend"]]] = {}

    def __init_subclass__(cls, **kwargs):
        super().__init_subclass__(**kwargs)
        for keyword in getattr(cls, "KEYWORDS", ()):
            Backend._REGISTRY[keyword.lower()] = cls
        Backend._REGISTRY[f"{cls.IDENTIFIER.lower()}@{cls.VERSION}"] = cls

    def __init__(self, *, configuration=None, general_configuration=None):
        self._configuration = self._prepare_backend_configuration(configuration)
        self._general_configuration = self._prepare_general_configuration(
            general_configuration
        )

    @classmethod
    def default_configuration_path(cls):
        """Return the default JSON configuration path for this backend."""
        return Configuration.default_file(cls.IDENTIFIER)

    @classmethod
    def has_default_configuration(cls) -> bool:
        """Return whether the default backend JSON file exists."""
        return cls.default_configuration_path().exists()

    @property
    def is_available(self) -> bool:
        """Return whether this backend has a persisted default configuration."""
        return type(self).has_default_configuration()

    @property
    def configuration(self) -> Configuration:
        return self._configuration

    @property
    def general_configuration(self) -> Configuration:
        return self._general_configuration

    @classmethod
    def _prepare_backend_configuration(cls, configuration):
        if configuration is None:
            return Configuration.for_backend(cls.IDENTIFIER)
        if not isinstance(configuration, Configuration):
            raise TypeError("configuration must be a Configuration")
        return configuration.clone()

    @classmethod
    def _prepare_general_configuration(cls, configuration):
        if configuration is None:
            return Configuration.general()
        if not isinstance(configuration, Configuration):
            raise TypeError("general_configuration must be a Configuration")
        return configuration.clone()

    def clone(self, *, configuration=None, general_configuration=None):
        return type(self)(
            configuration=self.configuration.clone()
            if configuration is None
            else configuration,
            general_configuration=self.general_configuration.clone()
            if general_configuration is None
            else general_configuration,
        )

    def configure(
        self,
        *,
        configuration=None,
        general_configuration=None,
        backend=None,
        general=None,
    ):
        new_backend = self.configuration.clone()
        new_general = self.general_configuration.clone()
        if configuration is not None:
            new_backend.update(configuration)
        if backend is not None:
            new_backend.update(backend)
        if general_configuration is not None:
            new_general.update(general_configuration)
        if general is not None:
            new_general.update(general)
        return type(self)(
            configuration=new_backend,
            general_configuration=new_general,
        )

    @contextmanager
    def configured(self, **kwargs):
        yield self.configure(**kwargs)

    @classmethod
    def get(cls, keyword: str, *, version: str | None = None, **kwargs):
        _ensure_backend_registry_loaded()
        key = keyword.lower()
        if version is not None:
            lookup = f"{key}@{version}"
            if lookup in cls._REGISTRY:
                return cls._REGISTRY[lookup](**kwargs)
        if key not in cls._REGISTRY:
            raise KeyError(f"unknown backend keyword {keyword!r}")
        return cls._REGISTRY[key](**kwargs)

    def create_builder(self, **params):
        if type(self).BUILDER_CLASS is None:
            raise ValueError(f"{type(self).__name__} has no builder class")
        return type(self).BUILDER_CLASS(
            f"backend:{type(self).IDENTIFIER}",
            **params,
        )

    def default_optimizers(self):
        optimizers = [optimizer() for optimizer in type(self).DEFAULT_OPTIMIZERS]
        threshold = self.configuration.get_nested(
            "optimizers",
            "auto_parametric_threshold",
            default=None,
        )
        if threshold:
            optimizers.append(
                AutoParametricGroupOptimizer(threshold=int(threshold))
            )
        return optimizers

    def default_validators(self):
        return [validator() for validator in type(self).DEFAULT_VALIDATORS]

    def create_build_chain(
        self,
        *,
        builder=None,
        optimizers=None,
        validators=None,
    ):
        if builder is None:
            builder = self.create_builder()
        chain = type(self).BUILDCHAIN_CLASS(
            builder,
            optimizers=[
                *self.default_optimizers(),
                *(optimizers or []),
            ],
            validators=[
                *self.default_validators(),
                *(validators or []),
            ],
        )
        return chain

    def create_resource(self, name: str = "default", **overrides):
        factories = self.get_resource_factories()
        key = name.lower()
        if key not in factories:
            raise KeyError(
                f"resource preset {name!r} is not available for {self.IDENTIFIER}"
            )
        resource = factories[key](**overrides)
        if not isinstance(resource, ComputeResource):
            raise TypeError("resource factories must return ComputeResource instances")
        return resource

    def get_resource_factories(self) -> dict[str, Any]:
        return {}

    def default_resource_name(self) -> str:
        parallel_model = str(
            self.configuration.get_nested(
                "resource", "parallel_model", default="default"
            )
        ).lower()
        if parallel_model in self.get_resource_factories():
            return parallel_model
        return "default"

    def default_resource(self):
        return self.create_resource(self.default_resource_name())

    def library(self, plain_name, *, resource=None, **kwargs):
        if type(self).LIBRARY_CLASS is None:
            raise ValueError(f"{type(self).__name__} has no library class")
        if resource is None:
            resource = self.default_resource()
        return type(self).LIBRARY_CLASS(
            plain_name,
            resource=resource,
            configuration=self.configuration.clone(),
            general_configuration=self.general_configuration.clone(),
            **kwargs,
        ).attach_backend(self)

    def wrap_library(self, library, *, wrapper_lib=None, build=False, **kwargs):
        self.ensure_compatible_library(library)
        if type(self).WRAPPER_LIBRARY_CLASS is None:
            raise ValueError(
                f"{type(self).__name__} does not define a wrapper library"
            )
        if build:
            library.build()
        if wrapper_lib is None:
            wrapper_lib = self.resolve_default_wrapper_lib(library)
        return type(self).WRAPPER_LIBRARY_CLASS(
            library,
            wrapper_lib=wrapper_lib,
            **kwargs,
        )

    def resolve_default_wrapper_lib(self, library):
        return None

    def import_python_module(self, library):
        self.ensure_compatible_library(library)
        return library.import_python_module()

    def wrapped(
        self,
        libroutine_name,
        library,
        *,
        wrapper_lib=None,
        build=False,
        daa_assignments=None,
        reuse_buffer=False,
        **kwargs,
    ):
        wrappers = self.wrap_library(
            library,
            wrapper_lib=wrapper_lib,
            build=build,
            **kwargs,
        )
        return wrappers.create_wrapper(
            libroutine_name,
            daa_assignments=daa_assignments,
            reuse_buffer=reuse_buffer,
        )

    def make_daa_assignments(self, config_map):
        assignments = {}
        for instruction_var, spec in config_map.items():
            assignments[instruction_var] = self._assignment_from_spec(
                instruction_var,
                spec,
            )
        return assignments

    def ensure_compatible_library(self, library):
        if type(self).LIBRARY_CLASS is None:
            raise ValueError(f"{type(self).__name__} has no library class")
        if not isinstance(library, type(self).LIBRARY_CLASS):
            raise TypeError(
                f"{type(self).__name__} can only populate "
                f"{type(self).LIBRARY_CLASS.__name__} instances, got "
                f"{type(library).__name__}"
            )
        return library

    def select_resource(self, *, resource=None, resource_name=None):
        if resource is not None and resource_name is not None:
            raise ValueError("set either resource or resource_name, not both")
        if resource is not None:
            return resource
        if resource_name is not None:
            return self.create_resource(resource_name)
        return None

    def libroutine_from_instructions(
        self,
        library,
        name,
        *instructions,
        builder=None,
        optimizers=None,
        validators=None,
        daa_assignments=None,
        assignment_config=None,
        lrv_assignments=None,
        container_class=None,
        namespace=None,
        resource=None,
        resource_name=None,
        detailed_record=False,
        **buildargs,
    ):
        self.ensure_compatible_library(library)
        if daa_assignments is None and assignment_config is not None:
            daa_assignments = self.make_daa_assignments(assignment_config)
        selected_resource = self.select_resource(
            resource=resource,
            resource_name=resource_name,
        )
        log.info(
            f"Backend {self.IDENTIFIER} starts routine creation: {name}",
            f"library: {library.libname}",
            f"assignment entries: {0 if daa_assignments is None else len(daa_assignments)}",
            f"resource: {'default' if selected_resource is None else type(selected_resource).__module__ + '.' + type(selected_resource).__qualname__}",
            source=type(self).__name__,
        )
        build_chain = self.create_build_chain(
            builder=builder,
            optimizers=optimizers,
            validators=validators,
        )
        optimized_instructions = build_chain.optimize(
            instructions,
            daa_assignments=daa_assignments,
            lrv_assignments=lrv_assignments,
            container_class=container_class,
            resource=selected_resource,
            **buildargs,
        )
        build_chain.validate(
            optimized_instructions,
            daa_assignments=daa_assignments,
            lrv_assignments=lrv_assignments,
            container_class=container_class,
            resource=selected_resource,
            **buildargs,
        )
        libroutine = build_chain.build_to_library(
            library,
            name,
            optimized_instructions,
            daa_assignments=daa_assignments,
            lrv_assignments=lrv_assignments,
            container_class=container_class,
            namespace=namespace,
            resource=selected_resource,
            detailed_record=detailed_record,
            **buildargs,
        )
        log.info(
            f"Backend {self.IDENTIFIER} finished routine creation: {name}",
            source=type(self).__name__,
        )
        return libroutine

    def _assignment_from_spec(self, instruction_var, spec):
        if isinstance(spec, tuple) and len(spec) == 2:
            return spec
        config = self.normalize_assignment_config(instruction_var, spec)
        adaa_class = self.resolve_assignment_adaa(instruction_var, config)
        status = self.resolve_assignment_status(config.status)
        if config.is_buffer:
            status |= LibRoutineVariable.STATUS_BUFFER
        return adaa_class, status

    def normalize_assignment_config(self, instruction_var, spec):
        if isinstance(spec, AssignmentConfig):
            config = spec
        elif isinstance(spec, str):
            config = AssignmentConfig(status=spec)
        elif isinstance(spec, dict):
            config = AssignmentConfig(**spec)
        else:
            raise TypeError(
                "assignment config must be a status string, AssignmentConfig, "
                "dict, or existing (adaa_class, status) tuple"
            )
        family = config.family
        if family is None and config.factory is None and config.adaa_class is None:
            family = self._legacy_family_from_config(config)
        layout = config.layout
        if layout is None:
            layout = _default_keymap_for(instruction_var)
        selected = config.selected_keys or config.components
        return replace(
            config,
            family=family,
            layout=layout,
            selected_keys=None if selected is None else tuple(selected),
            options={} if config.options is None else dict(config.options),
        )

    def _legacy_family_from_config(self, config: AssignmentConfig) -> str | None:
        if config.real is None and config.imag is None:
            return None
        real = True if config.real is None else bool(config.real)
        imag = True if config.imag is None else bool(config.imag)
        if real and imag:
            return "complex"
        if real:
            return "real"
        if imag:
            return "imag"
        raise ValueError("legacy assignment config disables both real and imag")

    def resolve_assignment_status(self, status: str | int):
        if isinstance(status, int):
            return status
        normalized = status.upper().strip()
        aliases = {
            "R": LibRoutineVariable.STATUS_INPUT,
            "READ": LibRoutineVariable.STATUS_INPUT,
            "IN": LibRoutineVariable.STATUS_INPUT,
            "INPUT": LibRoutineVariable.STATUS_INPUT,
            "W": LibRoutineVariable.STATUS_OUTPUT,
            "WRITE": LibRoutineVariable.STATUS_OUTPUT,
            "OUT": LibRoutineVariable.STATUS_OUTPUT,
            "OUTPUT": LibRoutineVariable.STATUS_OUTPUT,
            "RW": LibRoutineVariable.STATUS_INOUT,
            "WR": LibRoutineVariable.STATUS_INOUT,
            "READWRITE": LibRoutineVariable.STATUS_INOUT,
            "INOUT": LibRoutineVariable.STATUS_INOUT,
            "B": LibRoutineVariable.STATUS_INOUT | LibRoutineVariable.STATUS_BUFFER,
            "BUFFER": LibRoutineVariable.STATUS_INOUT | LibRoutineVariable.STATUS_BUFFER,
        }
        if normalized not in aliases:
            raise ValueError(f"unknown assignment status {status!r}")
        return aliases[normalized]

    def resolve_assignment_adaa(self, instruction_var, config: AssignmentConfig):
        adaa_class = self.resolve_assignment_base_class(instruction_var, config)
        adaa_class = self.apply_assignment_layout(
            adaa_class,
            instruction_var=instruction_var,
            config=config,
        )
        adaa_class = self.apply_assignment_component_selection(
            adaa_class,
            instruction_var=instruction_var,
            config=config,
        )
        self.validate_assignment_dtype(
            adaa_class,
            instruction_var=instruction_var,
            config=config,
        )
        return adaa_class

    def get_assignment_families(self) -> dict[str, Any]:
        families = dict(type(self).ADAA_FAMILIES)
        if "complex" not in families and type(self).COMPLEX_ADAA_CLASS is not None:
            families["complex"] = type(self).COMPLEX_ADAA_CLASS
        if "real" not in families and type(self).REAL_ADAA_CLASS is not None:
            families["real"] = type(self).REAL_ADAA_CLASS
        if "imag" not in families and type(self).IMAG_ADAA_CLASS is not None:
            families["imag"] = type(self).IMAG_ADAA_CLASS
        if "default" not in families:
            if "complex" in families:
                families["default"] = families["complex"]
            elif families:
                first_key = next(iter(families))
                families["default"] = families[first_key]
        return families

    def resolve_assignment_family(self, family: str):
        families = self.get_assignment_families()
        key = family.lower()
        if key not in families:
            raise KeyError(
                f"assignment family {family!r} is not available for {self.IDENTIFIER}"
            )
        return families[key]

    def resolve_assignment_base_class(
        self,
        instruction_var,
        config: AssignmentConfig,
    ) -> type[GenericADAA]:
        base = config.adaa_class
        if base is None and config.factory is not None:
            base = self._invoke_assignment_factory(
                config.factory,
                instruction_var=instruction_var,
                config=config,
            )
        if base is None:
            family = config.family or "default"
            base = self._invoke_assignment_factory(
                self.resolve_assignment_family(family),
                instruction_var=instruction_var,
                config=config,
            )
        if not isinstance(base, type) or not issubclass(base, GenericADAA):
            raise TypeError(
                "assignment resolution must yield an ADAA/DAA class derived "
                "from GenericADAA"
            )
        return base

    def _invoke_assignment_factory(
        self,
        factory,
        *,
        instruction_var,
        config: AssignmentConfig,
    ):
        if isinstance(factory, type) and issubclass(factory, GenericADAA):
            return factory
        if callable(factory):
            return factory(
                backend=self,
                instruction_var=instruction_var,
                config=config,
            )
        raise TypeError("assignment factories must be ADAA classes or callables")

    def apply_assignment_layout(
        self,
        adaa_class: type[GenericADAA],
        *,
        instruction_var,
        config: AssignmentConfig,
    ) -> type[GenericADAA]:
        layout = config.layout
        if layout is not None:
            adaa_class = self._apply_layout_spec(
                adaa_class,
                layout=layout,
                instruction_var=instruction_var,
                config=config,
            )
        if config.size is not None and getattr(adaa_class, "_FIXED_SIZE", None) is None:
            adaa_class = adaa_class.fix_size(config.size)
        return adaa_class

    def _apply_layout_spec(
        self,
        adaa_class: type[GenericADAA],
        *,
        layout,
        instruction_var,
        config: AssignmentConfig,
    ) -> type[GenericADAA]:
        if isinstance(layout, type) and issubclass(layout, GenericADAA):
            return layout
        if isinstance(layout, KeyMap):
            if getattr(adaa_class, "_KEYMAP", None) is None:
                return adaa_class.set_keymap(layout)
            return adaa_class
        if isinstance(layout, int):
            if getattr(adaa_class, "_FIXED_SIZE", None) is None:
                return adaa_class.fix_size(layout)
            return adaa_class
        if isinstance(layout, dict):
            target = adaa_class
            if "factory" in layout:
                target = self._invoke_assignment_factory(
                    layout["factory"],
                    instruction_var=instruction_var,
                    config=config,
                )
            if "keymap" in layout and getattr(target, "_KEYMAP", None) is None:
                target = target.set_keymap(layout["keymap"])
            if "size" in layout and getattr(target, "_FIXED_SIZE", None) is None:
                target = target.fix_size(layout["size"])
            if "selected_keys" in layout or "components" in layout:
                keys = layout.get("selected_keys", layout.get("components"))
                target = target.only(*keys)
            return target
        if hasattr(layout, "apply_to_adaa_class"):
            return layout.apply_to_adaa_class(
                adaa_class,
                backend=self,
                instruction_var=instruction_var,
                config=config,
            )
        if callable(layout):
            return layout(
                adaa_class,
                backend=self,
                instruction_var=instruction_var,
                config=config,
            )
        raise TypeError(
            "layout must be a KeyMap, fixed size integer, GenericADAA class, "
            "mapping, callable, or object implementing apply_to_adaa_class"
        )

    def apply_assignment_component_selection(
        self,
        adaa_class: type[GenericADAA],
        *,
        instruction_var,
        config: AssignmentConfig,
    ) -> type[GenericADAA]:
        del instruction_var
        selected = config.selected_keys or config.components
        if selected:
            return adaa_class.only(*selected)
        return adaa_class

    def validate_assignment_dtype(
        self,
        adaa_class: type[GenericADAA],
        *,
        instruction_var,
        config: AssignmentConfig,
    ) -> None:
        del instruction_var
        if config.dtype is None:
            return
        datatypes = {dtype for _, dtype in adaa_class.datatypes()}
        if config.dtype not in datatypes:
            raise NotImplementedError(
                f"{type(self).__name__} cannot switch ADAA dtype to "
                f"{config.dtype!r} with the current ADAA family/factory result"
            )


def _ensure_backend_registry_loaded():
    global _BACKEND_REGISTRY_LOADED
    if _BACKEND_REGISTRY_LOADED:
        return
    for module_name in _BACKEND_MODULES:
        import_module(module_name)
    _BACKEND_REGISTRY_LOADED = True


def get_backend(keyword: str, *, version: str | None = None, **kwargs):
    """Return a backend instance by keyword or keyword/version pair."""
    return Backend.get(keyword, version=version, **kwargs)


__all__ = [
    "AssignmentConfig",
    "Backend",
    "Config",
    "get_backend",
]
